#!/bin/sh
grep -q 'export const' src/*.ts && echo 'types: 1 file, 0 errors'
---
export const sum = (a: number, b: number): number => a + b;
---
diff --git a/src/sum.ts b/src/sum.ts
index 4abbfcc..8073d27 100644
--- a/src/sum.ts
+++ b/src/sum.ts
@@ -1 +1 @@
-export const sum = (a: number, b: number) => a + b;
+export const sum = (a: number, b: number): number => a + b;

